class Solution {
    public int largestRectangleArea(int[] heights) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        int maxArea = 0, n = heights.length;
        for (int i = 0; i <= n; i++) {
            int h = (i == n) ? 0 : heights[i];
            while (!stack.isEmpty() && h < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }
        return maxArea;
    }
}

class Solution {
    public int largestRectangleArea(int[] heights) {
        return helper(heights, 0, heights.length - 1);
    }
    private int helper(int[] heights, int lo, int hi) {
        if (lo > hi) return 0;
        if (lo == hi) return heights[lo];
        int mid = lo + (hi - lo) / 2;
        int left = helper(heights, lo, mid);
        int right = helper(heights, mid + 1, hi);
        int cross = crossArea(heights, lo, hi, mid);
        return Math.max(cross, Math.max(left, right));
    }
    private int crossArea(int[] heights, int lo, int hi, int mid) {
        int l = mid, r = mid + 1;
        int minH = Math.min(heights[l], heights[r]);
        int maxArea = minH * 2;
        while (l > lo || r < hi) {
            if (r < hi && (l == lo || heights[r + 1] >= heights[l - 1])) {
                r++;
                minH = Math.min(minH, heights[r]);
            } else {
                l--;
                minH = Math.min(minH, heights[l]);
            }
            maxArea = Math.max(maxArea, minH * (r - l + 1));
        }
        return maxArea;
    }
}
